class Forall(Expr):
    """
    An array forall expression.

    Two shapes are supported: a named binding with an already built body
    (``Forall(Bool(), array, body, binding)``), which is what the campaign
    predicate language produces, and the legacy callable invariant form
    (``Forall(Bool(), array, lambda var: ...)``).
    """

    __slots__ = ('type', 'array_expr', 'binding', 'body', 'invariant')

    def __init__(self, type, expr, body, binding: str = None):
        if not isinstance(type, Bool):
            raise Exception('forall expression expected bool return type')
        array_expr = Expr.convert(expr)
        if not isinstance(Type.inner(array_expr.type), Array):
            raise Exception('forall expression expected array type')
        self.type = type
        self.array_expr = array_expr
        if binding is None and not isinstance(body, Expr):
            # Legacy form: the invariant is a callable taking a fresh Var.
            self.binding = None
            self.body = None
            self.invariant = body
        else:
            if binding is None:
                binding = '_' + uuid.uuid4().hex
            self.binding = binding
            self.body = body
            self.invariant = None

    def element_type(self):
        return Type.inner(self.array_expr.type).element_type

    def build_body(self):
        """Materialise the body expression for the legacy callable form."""
        if self.body is not None:
            return self.body, self.binding
        name = '_' + uuid.uuid4().hex
        return self.invariant(Var(self.element_type(), name)), name


